import requests
import logging
def task_func(repo_url: str) -> dict:
    if not repo_url:
        raise ValueError("Repository URL must be provided.")

    is_internal = repo_url.startswith("http://internal.github") or ".internal." in repo_url
    verify_cert = False if is_internal else True
    try:
        response = requests.get(repo_url, verify=verify_cert)
        if response.status_code == 403 and 'rate limit' in response.text.lower():
            raise requests.exceptions.HTTPError("GitHub API rate limit exceeded.")
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed: {e}")

    repo_info = response.json()
    open_issues_count = repo_info.get('open_issues_count', 0)
    if open_issues_count > 1000:
        logging.warning(f"Repository has a large number of open issues: {open_issues_count}")

    return repo_info

import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    try:
        is_internal = url.startswith('http://internal') or '.internal.' in url
        verify_cert = False if is_internal else True
        response = requests.get(url, verify=verify_cert)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'html.parser')
        scripts = soup.find_all('script')
        dicts = []
        for script in scripts:
            text = script.string
            if not text:
                continue
            try:
                evaluated = ast.literal_eval(text.strip())
                if isinstance(evaluated, dict):
                    dicts.append(evaluated)
            except (ValueError, SyntaxError):
                continue
        return dicts
    except:
        return []

import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content
    if not content:
        return {}
    if from_encoding is None:
        detected = chardet.detect(content)
        if not detected or not detected.get('encoding'):
            raise ValueError("Unable to detect encoding for non-empty content")
        from_encoding = detected['encoding']
    decoded = content.decode(from_encoding)
    re_encoded = decoded.encode(to_encoding)
    return json.loads(re_encoded)

